spec.expr:
sum by (event_data_error_type) (
  rate({app=~"$app", source="faro"} | logfmt | browser_name =~ "$browser" | browser_os =~ "$os" | page_id =~ "$page_id" | event_name = "request_failed" | app_environment =~ "$environment" | user_attr_role =~ "$role" | app_version =~ "$app_version" | event_data_client =~ "$client" | event_data_error_type =~ "$error_type" | event_data_status =~ "$status" [1m])
)

sum by (event_data_client) (
  rate({app=~"$app", source="faro"} | logfmt | browser_name =~ "$browser" | browser_os =~ "$os" | page_id =~ "$page_id" | event_name = "request_failed" | app_environment =~ "$environment" | user_attr_role =~ "$role" | app_version =~ "$app_version" | event_data_client =~ "$client" | event_data_error_type =~ "$error_type" | event_data_status =~ "$status" [1m])
)

sum by (event_data_status) (
  count_over_time({app=~"$app", source="faro"} | logfmt | browser_name =~ "$browser" | browser_os =~ "$os" | page_id =~ "$page_id" | event_name = "request_failed" | event_data_error_type = "http" | app_environment =~ "$environment" | user_attr_role =~ "$role" | app_version =~ "$app_version" | event_data_client =~ "$client" | event_data_error_type =~ "$error_type" | event_data_status =~ "$status" [$__range])
)

topk(20,
  sum by (event_data_route_template, event_data_status) (
    count_over_time({app=~"$app", source="faro"} | logfmt | browser_name =~ "$browser" | browser_os =~ "$os" | page_id =~ "$page_id" | event_name = "request_failed" | app_environment =~ "$environment" | user_attr_role =~ "$role" | app_version =~ "$app_version" | event_data_client =~ "$client" | event_data_error_type =~ "$error_type" | event_data_status =~ "$status" [$__range])
  )
)
